referenceSolutionTemplate:
#include <stdio.h>

int total = 0;

void putIn(int x) {
    total = total + x;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int i;
    for (i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            return 1;
        }
        putIn(x);
    }

    printf("大缸里现在有 %d 条\n", total);
    return 0;
}
